248	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_gpt::prefill(const std::string& input_text) const {
249	    auto token_ids = bpe->encode(input_text, false, false);
250	    if (bos >= 0) token_ids.insert(token_ids.begin(), bos);
251	
252	    int last_token_id = token_ids.back();
253	    token_ids.pop_back();
254	
255	    ncnn::Mat cos_cache, sin_cache;
256	    if (rope_type == RoPE_Type::LongRoPE) {
257	        generate_rope_embed_cache_LongRoPE(token_ids.size(), rope_head_dim, 0, cos_cache, sin_cache, rope_theta, short_factor.data(), long_factor.data(), original_max_position_embeddings);
258	    } else if (rope_type == RoPE_Type::NTK_RoPE) {
259	        generate_ntk_rope_embed_cache(token_ids.size(), rope_head_dim, 0, cos_cache, sin_cache, rope_theta, ntk_scaling_params);
260	    } else if (rope_type == RoPE_Type::YARN_RoPE) {
261	        generate_yarn_rope_embed_cache(token_ids.size(), rope_head_dim, 0, cos_cache, sin_cache, rope_theta, ntk_scaling_params);
262	    }
263	    else
264	    {
265	        generate_rope_embed_cache(token_ids.size(), rope_head_dim, 0, cos_cache, sin_cache, rope_theta);
266	    }
267	
268	    ncnn::Mat input_ids_mat = ncnn::Mat((int)token_ids.size(), 1, (void*)token_ids.data()).clone();
269	    ncnn::Mat token_embed;
270	    {
271	        ncnn::Extractor ex = embed_net->create_extractor();
272	        ex.input("in0", input_ids_mat);
273	        ex.extract("out0", token_embed);
274	    }
275	
276	    ncnn::Mat mask((int)token_ids.size(), (int)token_ids.size());
277	    mask.fill(0.0f);
278	    for (int i = 0; i < (int)token_ids.size(); i++) {
279	        float* row = mask.row(i);
280	        for (int j = i + 1; j < (int)token_ids.size(); j++) {
281	            row[j] = -1e38f;
282	        }
283	    }
284	
285	    std::vector<std::pair<ncnn::Mat, ncnn::Mat>> kv_cache;
286	    std::vector<ncnn::Mat> sconv_cache;
287	    std::vector<ncnn::Mat> gdr_cache;
288	    ncnn::Mat decode_out;
289	    {
290	        ncnn::Extractor ex = decoder_net->create_extractor();
291	        ex.input("in0", token_embed);
292	        ex.input("in1", mask);
293	        ex.input("in2", cos_cache);
294	        ex.input("in3", sin_cache);
295	
296	        for (int i = 0; i < attn_cnt; i++) {
297	            char name_k_out[32], name_v_out[32];
298	            std::snprintf(name_k_out, sizeof(name_k_out), "out_cache_k%d", i);
299	            std::snprintf(name_v_out, sizeof(name_v_out), "out_cache_v%d", i);
300	            ncnn::Mat k_cache, v_cache;
301	            ex.extract(name_k_out, k_cache);
302	            ex.extract(name_v_out, v_cache);
303	            kv_cache.emplace_back(std::move(k_cache), std::move(v_cache));
304	        }
305	
306	        for (int i = 0; i < sconv_cnt; i++) {
307	            char name_out[32];
308	            std::snprintf(name_out, sizeof(name_out), "out_cache_conv%d", i);
309	            ncnn::Mat cache;
310	            ex.extract(name_out, cache);
311	            sconv_cache.emplace_back(std::move(cache));
312	        }
313	
314	        for (int i = 0; i < gdr_cnt; i++) {
315	            char name_out[32];
316	            std::snprintf(name_out, sizeof(name_out), "out_cache_gdr%d", i);
317	            ncnn::Mat cache;
318	            ex.extract(name_out, cache);
319	            gdr_cache.emplace_back(std::move(cache));
320	        }
321	    }
322	
323	    // Handle last token
324	    ncnn::Mat last_token_mat = ncnn::Mat(1, 1, (void*)&last_token_id).clone();
325	    ncnn::Mat last_token_embed;
326	    {
327	        ncnn::Extractor ex = embed_net->create_extractor();
328	        ex.input("in0", last_token_mat);
329	        ex.extract("out0", last_token_embed);
330	    }
331	    
332	    ncnn::Mat last_cos_cache, last_sin_cache;
333	    if (rope_type == RoPE_Type::LongRoPE) {
334	        generate_rope_embed_cache_LongRoPE(1, rope_head_dim, (int)token_ids.size(), last_cos_cache, last_sin_cache, rope_theta, short_factor.data(), long_factor.data(), original_max_position_embeddings);
335	    } else if (rope_type == RoPE_Type::NTK_RoPE) {
336	        generate_ntk_rope_embed_cache(1, rope_head_dim, (int)token_ids.size(), last_cos_cache, last_sin_cache, rope_theta, ntk_scaling_params);
337	    } else if (rope_type == RoPE_Type::YARN_RoPE) {
338	        generate_yarn_rope_embed_cache(1, rope_head_dim, (int)token_ids.size(), last_cos_cache, last_sin_cache, rope_theta, ntk_scaling_params);
339	    }
340	    else {
341	        generate_rope_embed_cache(1, rope_head_dim, (int)token_ids.size(), last_cos_cache, last_sin_cache, rope_theta);
342	    }
343	
344	    ncnn::Mat last_mask((int)token_ids.size() + 1, 1);
345	    last_mask.fill(0.0f);
346	
347	    {
348	        ncnn::Extractor ex = decoder_net->create_extractor();
349	        ex.input("in0", last_token_embed);
350	        ex.input("in1", last_mask);
351	        ex.input("in2", last_cos_cache);
352	        ex.input("in3", last_sin_cache);
353	
354	        for (int i = 0; i < attn_cnt; i++) {
355	            char name_k_in[16], name_v_in[16];
356	            std::snprintf(name_k_in, sizeof(name_k_in), "cache_k%d", i);
357	            std::snprintf(name_v_in, sizeof(name_v_in), "cache_v%d", i);
358	            ex.input(name_k_in, kv_cache[i].first);
359	            ex.input(name_v_in, kv_cache[i].second);
360	        }
361	
362	        for (int i = 0; i < sconv_cnt; i++) {
363	            char name_in[16];
364	            std::snprintf(name_in, sizeof(name_in), "cache_conv%d", i);
365	            ex.input(name_in, sconv_cache[i]);
366	        }
367	
368	        for (int i = 0; i < gdr_cnt; i++) {
369	            char name_in[16];
370	            std::snprintf(name_in, sizeof(name_in), "cache_gdr%d", i);
371	            ex.input(name_in, gdr_cache[i]);
372	        }
373	
374	        for (int i = 0; i < attn_cnt; i++) {
375	            char name_k_out[32], name_v_out[32];
376	            std::snprintf(name_k_out, sizeof(name_k_out), "out_cache_k%d", i);
377	            std::snprintf(name_v_out, sizeof(name_v_out), "out_cache_v%d", i);
378	            ncnn::Mat k_cache, v_cache;
379	            ex.extract(name_k_out, k_cache);
380	            ex.extract(name_v_out, v_cache);
381	            kv_cache[i] = std::make_pair(std::move(k_cache), std::move(v_cache));
382	        }
383	
384	        for (int i = 0; i < sconv_cnt; i++) {
385	            char name_out[32];
386	            std::snprintf(name_out, sizeof(name_out), "out_cache_conv%d", i);
387	            ncnn::Mat cache;
388	            ex.extract(name_out, cache);
389	            sconv_cache[i] = std::move(cache);
390	        }
391	
392	        for (int i = 0; i < gdr_cnt; i++) {
393	            char name_out[32];
394	            std::snprintf(name_out, sizeof(name_out), "out_cache_gdr%d", i);
395	            ncnn::Mat cache;
396	            ex.extract(name_out, cache);
397	            gdr_cache[i] = std::move(cache);
398	        }
399	
400	        ex.extract("out0", decode_out);
401	    }
402	
403	    ncnn::Mat logits;
404	    {
405	        ncnn::Extractor ex = proj_out_net->create_extractor();
406	        ex.input("in0", decode_out);
407	        ex.extract("out0", logits);
408	    }
409	
410	    int next_token_id = 0;
411	    {
412	        const float* p = logits;
413	        float max_val = p[0];
414	        for (int i = 1; i < logits.w; ++i) {
415	            if (p[i] > max_val) {
416	                max_val = p[i];
417	                next_token_id = i;
418	            }
419	        }
420	    }
421	
422	    auto ctx = create_ctx(sconv_cnt, gdr_cnt);
423	    ctx->kv_cache = std::move(kv_cache);
424	    ctx->cur_token = next_token_id;
425	    ctx->position_id = (int)token_ids.size() + 1;
426	    
427	    if (sconv_cnt > 0 || gdr_cnt > 0) {
428	        auto qwen_ctx = std::dynamic_pointer_cast<qwen3_5_ctx>(ctx);
429	        if (qwen_ctx) {
430	            qwen_ctx->sconv_cache = std::move(sconv_cache);
431	            qwen_ctx->gdr_cache = std::move(gdr_cache);
432	        }
433	    }
434	    
435	    return ctx;
436	}
