844	    const int vocab_size = bpe->vocab_size();
845	
846	    auto handle_tool = [&](const std::string& tool_call_text, std::shared_ptr<ncnn_llm_gpt_ctx>& ctx_ref) {
847	        nlohmann::json tool_call_json;
848	        try {
849	            tool_call_json = nlohmann::json::parse(tool_call_text);
850	        } catch (const std::exception& e) {
851	            tool_call_json = nlohmann::json::object();
852	        }
853	
854	        nlohmann::json tool_resp;
855	        if (cfg.tool_callback) {
856	            tool_resp = cfg.tool_callback(tool_call_json);
857	        } else {
858	            tool_resp = nlohmann::json{{"tool_call", tool_call_json}};
859	        }
860	
861	        std::string tool_response_pre = "<|im_end|>\n<|im_start|>user\n<tool_response>\n\n";
862	        std::string tool_response_post = "\n\n</tool_response><|im_end|>\n<|im_start|>assistant\n<think>\n</think>\n\n";
863	
864	        ctx_ref = prefill(tool_response_pre + tool_resp.dump() + tool_response_post, ctx_ref);
