999	int ncnn_llm_gpt::get_scaled_image_size(float scale, int size, int effective_patch_size) const {
1000	    float scaled_size_f = (float)size * scale;
1001	    int scaled_size = (int)(std::ceil(scaled_size_f / (float)effective_patch_size) * effective_patch_size);
1002	    return std::max(effective_patch_size, scaled_size);
