1005	void ncnn_llm_gpt::get_image_size_for_patches(int image_height, int image_width, int patch_size, int max_num_patches, int& target_height, int& target_width) const {
1006	    float scale = 1.0f;
1007	    int effective_patch_size = patch_size * 2;
1008	    while (true) {
1009	        target_height = get_scaled_image_size(scale, image_height, effective_patch_size);
1010	        target_width = get_scaled_image_size(scale, image_width, effective_patch_size);
1011	        long long num_patches = ((long long)target_height / patch_size) * ((long long)target_width / patch_size);
1012	        if (num_patches > max_num_patches) {
1013	            scale -= 0.02f;
1014	        } else {
1015	            break;
1016	        }
1017	    }
1018	}
